import datetime, hashlib, re
from pathlib import Path
import yaml

class UniqueLoader(yaml.SafeLoader):
    pass

def unique_mapping(loader, node, deep=False):
    loader.flatten_mapping(node)
    result = {}
    for key_node, value_node in node.value:
        key = loader.construct_object(key_node, deep=deep)
        if key in result:
            raise ValueError(f"Duplicate YAML field: {key}")
        result[key] = loader.construct_object(value_node, deep=deep)
    return result

UniqueLoader.add_constructor(yaml.resolver.BaseResolver.DEFAULT_MAPPING_TAG, unique_mapping)

def evaluate_report(report_path, evaluated_head):
    observed_at = datetime.datetime.now(datetime.timezone.utc).isoformat()
    result = {"verdict": "FAIL", "evaluated_at": observed_at,
              "evaluated_head": evaluated_head, "rationale": None,
              "waiver": None, "consumed_report_sha256": None, "blockers": []}
    try:
        raw = Path(report_path).read_bytes()
        result["consumed_report_sha256"] = hashlib.sha256(raw).hexdigest()
        report = yaml.load(raw.decode("utf-8"), Loader=UniqueLoader)
    except (OSError, UnicodeError, yaml.YAMLError, ValueError, TypeError) as error:
        result["rationale"] = f"Missing or unreadable report: {type(error).__name__}: {error}"
        return result
    if not isinstance(report, dict) or type(report.get("schema_version")) is not int or report["schema_version"] != 1:
        result["rationale"] = "Unsupported or missing schema_version; expected integer 1."
        return result
    source = report.get("source")
    if not isinstance(source, dict) or source.get("git_head") != evaluated_head:
        result["rationale"] = "Stale or missing source.git_head; it must match the evaluated branch head."
        return result
    if not isinstance(source.get("profile"), str) or source.get("profile") not in {"issue-per-task", "epic-based", "milestone-based", "kanban", "generic"}:
        result["rationale"] = "Missing or unsupported source.profile."
        return result
    rows = report.get("rows")
    count = source.get("release_plan_entry_count")
    if not isinstance(rows, list) or type(count) is not int or count < 1 or len(rows) != count:
        result["rationale"] = "Omitted or malformed rows: row count differs from the report-mode release-plan inventory."
        return result
    seen = set()
    for row in rows:
        if not isinstance(row, dict) or not isinstance(row.get("entry_id"), str) or not row["entry_id"].strip() or row["entry_id"] in seen:
            result["rationale"] = "Missing or duplicate release-plan entry_id."
            return result
        seen.add(row["entry_id"])
        if not isinstance(row.get("title"), str) or not row["title"].strip():
            result["rationale"] = f"Missing row title: {row['entry_id']}"
            return result
        if not isinstance(row.get("status"), str) or row.get("status") not in {"todo", "planned", "active", "in-progress", "done", "blocked", "unknown", "deferred", "out-of-scope"}:
            result["rationale"] = f"Unsupported or missing row status: {row['entry_id']}"
            return result
        for field in ("implementation_evidence", "test_evidence", "verification_evidence", "disposition"):
            if not isinstance(row.get(field), dict):
                result["rationale"] = f"Missing or malformed {field}: {row['entry_id']}"
                return result
        implementation = row["implementation_evidence"]
        tests = row["test_evidence"]
        if row.get("priority") is not None and (not isinstance(row["priority"], str) or row["priority"] not in {"P0", "P1", "P2", "P3"}):
            result["rationale"] = f"Unsupported priority: {row['entry_id']}"
            return result
        declared_scenarios = row.get("required_scenarios", [])
        if not isinstance(declared_scenarios, list) or any(not isinstance(value, str) or not value.strip() for value in declared_scenarios):
            result["rationale"] = f"Malformed required_scenarios: {row['entry_id']}"
            return result
        if not isinstance(row.get("requirements"), list) or any(not isinstance(value, str) or not value.strip() for value in row["requirements"]):
            result["rationale"] = f"Malformed requirements: {row['entry_id']}"
            return result
        if not isinstance(row["disposition"].get("state"), str) or row["disposition"].get("state") not in {"active", "deferred", "out-of-scope"}:
            result["rationale"] = f"Unsupported or missing disposition.state: {row['entry_id']}"
            return result
        for evidence, fields in ((row["implementation_evidence"], ("changed_paths", "commits")),
                                 (row["test_evidence"], ("scenarios", "commands")),
                                 (row["verification_evidence"], ("receipts",))):
            if any(not isinstance(evidence.get(field), list) for field in fields):
                result["rationale"] = f"Malformed evidence lists: {row['entry_id']}"
                return result
        if any(not isinstance(value, str) or not value.strip() for value in implementation["changed_paths"] + tests["scenarios"]):
            result["rationale"] = f"Malformed changed-path or scenario evidence: {row['entry_id']}"
            return result
        if any(not isinstance(value, dict) or not re.fullmatch(r"(?:[0-9a-f]{40}|[0-9a-f]{64})", str(value.get("sha", ""))) for value in implementation["commits"]):
            result["rationale"] = f"Malformed commit evidence: {row['entry_id']}"
            return result
        if any(not isinstance(value, dict) or not isinstance(value.get("command"), str) or not value["command"].strip() for value in tests["commands"]):
            result["rationale"] = f"Malformed command evidence: {row['entry_id']}"
            return result
    missing = []
    failed = []
    excluded_without_owner = []
    highest_without_acceptance = []
    priorities = [row.get("priority") for row in rows if row.get("priority") in {"P0", "P1", "P2", "P3"}]
    highest = min(priorities) if priorities else None
    for row in rows:
        entry = row["entry_id"]
        disposition = row["disposition"]
        excluded = disposition["state"] in {"deferred", "out-of-scope"}
        if excluded:
            if any(not isinstance(disposition.get(field), str) or not disposition[field].strip() for field in ("owner", "rationale")):
                excluded_without_owner.append({"entry_id": entry, "reason": "Excluded row lacks owner or rationale."})
        elif row["status"] in {"deferred", "out-of-scope"}:
            missing.append({"entry_id": entry, "reason": "Excluded status without a matching owned disposition."})
        else:
            implementation = row["implementation_evidence"]
            tests = row["test_evidence"]
            verification = row["verification_evidence"]
            absent = []
            if not implementation["changed_paths"] and not implementation["commits"]:
                absent.append("implementation")
            declared = set(row.get("required_scenarios", []))
            observed = set(tests["scenarios"])
            if (not observed or declared - observed or not any(type(command.get("exit_code")) is int and command["exit_code"] == 0 for command in tests["commands"])):
                absent.append("test/acceptance")
            if not verification["receipts"] or not verification.get("behavior_smoke"):
                absent.append("verification/behavior-smoke")
            if absent:
                missing.append({"entry_id": entry, "reason": "Required evidence absent: " + ", ".join(absent)})
        smoke = row["verification_evidence"].get("behavior_smoke")
        if smoke is not None and (not isinstance(smoke, dict) or smoke.get("passed") is not True):
            failed.append({"entry_id": entry, "reason": "Actual behavior-smoke evidence is malformed or did not pass."})
        for command in row["test_evidence"]["commands"]:
            if command.get("exit_code") is not None and (type(command["exit_code"]) is not int or command["exit_code"] != 0):
                failed.append({"entry_id": entry, "reason": "Actual command evidence failed or has a malformed exit code."})
        for item in row["verification_evidence"]["receipts"]:
            receipt = item.get("receipt") if isinstance(item, dict) else None
            gate = receipt.get("gate") if isinstance(receipt, dict) else None
            if (not isinstance(gate, dict) or receipt.get("operation") != "truenorth_verify_gate"
                or type(receipt.get("schema_version")) is not int or receipt["schema_version"] != 1
                or gate.get("status") != "pass" or type(gate.get("exit_code")) is not int
                or gate["exit_code"] != 0 or gate.get("expectation") != "zero"):
                failed.append({"entry_id": entry, "reason": "Failed, malformed or unsupported real verification receipt."})
        if highest is not None and row.get("priority") == highest and not excluded:
            if not row["test_evidence"]["scenarios"] or not row.get("requirements") or not row["verification_evidence"].get("behavior_smoke"):
                highest_without_acceptance.append({"entry_id": entry, "reason": "Highest-priority task lacks actual test/acceptance coverage."})
    if missing:
        result["rationale"] = f"Required implementation, test or verification evidence is missing for {len(missing)} active, done or unresolved entries."
        result["blockers"] = missing + failed + excluded_without_owner + highest_without_acceptance
        return result
    if failed:
        result["rationale"] = "A real verification receipt failed or is malformed; model judgment cannot override it."
        result["blockers"] = failed + excluded_without_owner + highest_without_acceptance
        return result
    if excluded_without_owner:
        result["rationale"] = "A deferred or out-of-scope row lacks a legitimate recorded owner or rationale."
        result["blockers"] = excluded_without_owner + highest_without_acceptance
        return result
    if highest_without_acceptance:
        result["rationale"] = "Highest-priority task lacks actual test or acceptance coverage."
        result["blockers"] = highest_without_acceptance
        return result
    remaining = [{"entry_id":row["entry_id"],"gaps":row.get("gaps",[])} for row in rows if row["disposition"]["state"] == "active" and row.get("gaps")]
    if remaining:
        result["verdict"] = "CONCERNS"
        result["rationale"] = "Required records pass but non-blocking documented drift or evidence gaps remain; configured explicit override is required."
        result["blockers"] = remaining
        return result
    result["verdict"] = "PASS"
    result["rationale"] = "Every required record is present and passing. No waiver or exclusion was manufactured."
    return result
